  L61.list = m => keys().filter(k => L61.is(k, m));
  const cover = k => { if (kind(k) === 'book') { try { return coverInner(k); } catch (e) { return ''; } } let a = ''; try { a = ART[k] || ''; } catch (e) {} return a ? '<img src="' + esc(a) + '" alt="" loading="lazy">' : '<span class="d-l61ph">' + esc(name(k)) + '</span>'; };
